    (2, 3, 21, 86, 'D37B70D9', '1082543895', 3, '2026-06-09 00:00:00', 1926, 38, 38, 38, 'ALIMENTOS', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103005', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 87, '50FF49F4', '2968862905', 3, '2026-06-21 00:00:00', 2330, 822, 822, 822, 'INSUMOS OFICINA', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103005', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 88, '59F88CD3', '2965982277', 3, '2026-06-14 00:00:00', 2330, 416, 416, 416, 'INSUMOS OFICINA', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103005', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 89, '0515E855', '212945274', 3, '2026-06-03 00:00:00', 2978, 60, 60, 60, 'PARQUEO', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, null, 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 90, 'D0EE4FB2', '660425664', 3, '2026-06-04 00:00:00', 2437, 169, 169, 169, 'CAR WASH', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103027', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 91, '2B27BEC8', '3220064158', 3, '2026-06-26 00:00:00', 3053, 135, 135, 135, 'ALIMENTOS', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, null, 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 92, '35076897', '2632273812', 3, '2026-06-30 00:00:00', 1976, 52, 52, 52, 'ALIMENTOS', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103034', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 93, 'BED23EB2', '1408975545', 3, '2026-06-30 00:00:00', 2992, 5, 5, 5, 'PARQUEO', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103011', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 94, 'A7334369', '3537848594', 3, '2026-06-30 00:00:00', 2994, 366, 366, 366, 'REUNION COMERCIAL', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103005', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null),
    (2, 3, 21, 95, '1C1309AF', '3346416740', 3, '2026-06-30 00:00:00', 1915, 37, 37, 37, 'ALIMENTOS', 2, 1, 7.7, 12, 'OLM', '2026-07-31 00:00:00', false, 0, 0, 0, false, 5, '6010103005', 1, 0, 0, '6010103031', 1, 0, 0, 0, 'O', 'O', 'I', null, 0, false, 'V', 0, null, null)) as x(loc, caja, sub, movimiento, serie, documento, tipo_doc, f_doc, proveedor, total, valor, total_factura, descripcion, clasif, moneda_int, cambio, pct_iva, usuario, f_ingreso,
      anticipo, valor_ret, exento, propina, calc_ret, pct_ret, cuenta, version, inguat, timbre, cuenta_prop, version_prop, g_super, g_regular, g_diesel,
      tipo_factura, tipo_gasto, persona_gasto, f_pres, exento_ant, aplica_inguat, estado, valor_mi, nombre_recibe, f_ing) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    select p.id into v_per from public.caja_periodos p join public.cajas_chicas c on c.id = p.caja_id where c.localidad_id = v_loc and c.codigo = r.caja and p.numero = r.sub;
    if v_per is null then d_s := d_s + 1; continue; end if;
    v_prov := null;
    select * into v_prov from public.proveedores where organizacion_id = v_org and codigo = r.proveedor order by (localidad_id = v_loc) desc limit 1;
    if v_prov.id is null then d_p := d_p + 1; end if;
    v_cta := null; v_cprop := null;
    if r.cuenta is not null then
      select k.id into v_cta from public.cuentas k join public.catalogos_cuentas c on c.id = k.catalogo_id
      where c.localidad_id = v_loc and k.codigo = r.cuenta order by (c.version = r.version) desc, c.activo desc, c.version desc limit 1;
      if v_cta is null then v_faltan := array_append(v_faltan, format('3-0%s %s', r.loc, r.cuenta)); end if;
    end if;
    if r.cuenta_prop is not null then
      select k.id into v_cprop from public.cuentas k join public.catalogos_cuentas c on c.id = k.catalogo_id
      where c.localidad_id = v_loc and k.codigo = r.cuenta_prop order by (c.version = r.version_prop) desc, c.activo desc, c.version desc limit 1;
    end if;
    v_tipo := case r.tipo_doc when 3 then 'FACTURA ELECTRÓNICA' when 5 then 'FACTURA ESPECIAL' when 9 then 'FACTURA PEQUEÑO CONTRIBUYENTE' when 11 then 'RECIBO' else 'OTRO' end;
    v_clas := case r.clasif when 2 then 'SERVICIOS' when 6 then 'SERVICIOS' when 4 then 'BIENES' when 3 then 'BIENES' when 5 then 'COMBUSTIBLE' when 9 then 'IMPORTACIÓN' else 'OTROS' end;
    -- IVA, IDP y base con la misma regla del sistema (preparar_caja_documento).
    select * into g from public.parametros_generales where localidad_id = v_loc order by id limit 1;
    v_idp := round(r.g_super * coalesce(g.idp_super, 0) + r.g_regular * coalesce(g.idp_regular, 0) + r.g_diesel * coalesce(g.idp_diesel, 0), 2);
    v_afecto := r.total - r.exento - v_idp - r.inguat - r.timbre;
    v_iva := case when v_tipo in ('FACTURA PEQUEÑO CONTRIBUYENTE', 'RECIBO', 'OTRO') or v_afecto <= 0 then 0 else round(v_afecto * r.pct_iva / (100 + r.pct_iva), 2) end;
    insert into public.caja_documentos (periodo_id, linea, serie, documento, tipo_documento, fecha, nit, proveedor_codigo, proveedor_nombre, fecha_presentacion, moneda_id, clasificacion,
      total, exento, galones_super, galones_regular, galones_diesel, idp, inguat, timbre_prensa, no_deducible, retencion, valor_retencion, porcentaje_iva, iva, base, justificacion,
      cuenta_gasto_id, contable, usuario, creado_por_nombre, creado_en,
      origen_anterior, movimiento_anterior, tipo_documento_anterior, tipo_documento_id, clasificacion_anterior, clasificacion_id, proveedor_id, valor_anterior, total_factura,
      moneda_integracion, valor_cambio_anterior, anticipo, propina, porcentaje_retencion, aplica_inguat, cuenta_codigo_anterior, version_cuenta_anterior, cuenta_propina_id,
      cuenta_propina_codigo_anterior, version_propina_anterior, tipo_factura, tipo_gasto_anterior, persona_gasto, exento_anterior, estado_anterior, valor_mi, nombre_recibe,
      fecha_ingreso_anterior, fecha_ing_anterior)
    values (v_per, r.movimiento, nullif(upper(trim(r.serie::text)), ''), upper(trim(coalesce(r.documento::text, 'S/N'))), v_tipo, coalesce(r.f_doc::timestamp::date, current_date),
      nullif(upper(replace(trim(v_prov.nit), '-', '')), ''), r.proveedor::text,
      upper(trim(coalesce(nullif(trim(v_prov.nombre_fiscal), ''), v_prov.nombre_comercial, r.nombre_recibe::text, 'PROVEEDOR ' || r.proveedor))),
      r.f_pres::timestamp::date, v_gtq, v_clas, r.total, r.exento, r.g_super, r.g_regular, r.g_diesel, v_idp, r.inguat, r.timbre, 0,
      coalesce(r.calc_ret::boolean, false), case when coalesce(r.calc_ret::boolean, false) then r.valor_ret else 0 end, r.pct_iva, v_iva, v_afecto - v_iva,
      nullif(trim(r.descripcion::text), ''), v_cta, true, upper(r.usuario::text), upper(r.usuario::text), r.f_ingreso::timestamp::timestamptz,
      'MIGRADO', r.movimiento, r.tipo_doc, (select x.id from public.tipos_documento_compra x where x.codigo = r.tipo_doc),
      r.clasif, (select x.id from public.clasificaciones_compra x where x.codigo = r.clasif), v_prov.id, r.valor, r.total_factura,
      r.moneda_int::integer, r.cambio::numeric, r.anticipo::boolean, r.propina::numeric, r.pct_ret::numeric, r.aplica_inguat::boolean, r.cuenta, r.version::integer, v_cprop,
      r.cuenta_prop, r.version_prop::integer, r.tipo_factura, r.tipo_gasto, r.persona_gasto, r.exento_ant::numeric, r.estado, r.valor_mi::numeric, r.nombre_recibe,
      r.f_ingreso::timestamp, r.f_ing::timestamp)
    on conflict (periodo_id, linea) do update set serie = excluded.serie, documento = excluded.documento, tipo_documento = excluded.tipo_documento, fecha = excluded.fecha,
      nit = excluded.nit, proveedor_codigo = excluded.proveedor_codigo, proveedor_nombre = excluded.proveedor_nombre, fecha_presentacion = excluded.fecha_presentacion,
      clasificacion = excluded.clasificacion, total = excluded.total, exento = excluded.exento, galones_super = excluded.galones_super, galones_regular = excluded.galones_regular,
      galones_diesel = excluded.galones_diesel, idp = excluded.idp, inguat = excluded.inguat, timbre_prensa = excluded.timbre_prensa, retencion = excluded.retencion,
      valor_retencion = excluded.valor_retencion, porcentaje_iva = excluded.porcentaje_iva, iva = excluded.iva, base = excluded.base, justificacion = excluded.justificacion,
      cuenta_gasto_id = excluded.cuenta_gasto_id, usuario = excluded.usuario, creado_por_nombre = excluded.creado_por_nombre, creado_en = excluded.creado_en,
      origen_anterior = 'MIGRADO', movimiento_anterior = excluded.movimiento_anterior, tipo_documento_anterior = excluded.tipo_documento_anterior,
      tipo_documento_id = excluded.tipo_documento_id, clasificacion_anterior = excluded.clasificacion_anterior, clasificacion_id = excluded.clasificacion_id,
      proveedor_id = excluded.proveedor_id, valor_anterior = excluded.valor_anterior, total_factura = excluded.total_factura, moneda_integracion = excluded.moneda_integracion,
      valor_cambio_anterior = excluded.valor_cambio_anterior, anticipo = excluded.anticipo, propina = excluded.propina, porcentaje_retencion = excluded.porcentaje_retencion,
      aplica_inguat = excluded.aplica_inguat, cuenta_codigo_anterior = excluded.cuenta_codigo_anterior, version_cuenta_anterior = excluded.version_cuenta_anterior,
      cuenta_propina_id = excluded.cuenta_propina_id, cuenta_propina_codigo_anterior = excluded.cuenta_propina_codigo_anterior,
      version_propina_anterior = excluded.version_propina_anterior, tipo_factura = excluded.tipo_factura, tipo_gasto_anterior = excluded.tipo_gasto_anterior,
      persona_gasto = excluded.persona_gasto, exento_anterior = excluded.exento_anterior, estado_anterior = excluded.estado_anterior, valor_mi = excluded.valor_mi,
      nombre_recibe = excluded.nombre_recibe, fecha_ingreso_anterior = excluded.fecha_ingreso_anterior, fecha_ing_anterior = excluded.fecha_ing_anterior
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then d_n := d_n + 1; else d_a := d_a + 1; end if;
  end loop;
  alter table public.caja_documentos enable trigger caja_documentos_preparar;
  alter table public.caja_documentos enable trigger caja_documentos_auditar;
  raise notice '%', format('Movimientos de subcajas: %s nuevos, %s actualizados, %s sin subcaja, %s con proveedor que no existe.', d_n, d_a, d_s, d_p);
  if cardinality(v_faltan) > 0 then raise notice 'Cuentas que no existen en el catálogo (el documento queda sin cuenta): %.', (select string_agg(distinct x, ', ') from unnest(v_faltan) x); end if;
end;
$migra$;

notify pgrst, 'reload schema';
